import java.util.*;
public class Phase8Harness{static int p=0;static List<String> f=new ArrayList<>();record Lock(boolean enabled,long timeout){}static boolean locked(Lock l,long idle){return l.enabled&&idle>=l.timeout;}static List<String> shortcuts(boolean onboarded){return onboarded?List.of("add_expense","voice_expense","open_dashboard"):List.of("open_dashboard");}static String widget(long left){return left>=0?"₹"+left/100+" left":"₹"+(-left)/100+" over";}static void eq(String n,Object e,Object a){if(Objects.equals(e,a))p++;else f.add(n+" expected "+e+" got "+a);}public static void main(String[]a){eq("lock off",false,locked(new Lock(false,60),99));eq("lock on",true,locked(new Lock(true,60),60));eq("shortcut count",3,shortcuts(true).size());eq("pre onboarding",1,shortcuts(false).size());eq("widget positive","₹300 left",widget(30000));eq("widget negative","₹50 over",widget(-5000));System.out.println("PASSED: "+p+" assertions");if(!f.isEmpty()){f.forEach(System.out::println);System.exit(1);}System.out.println("ALL PHASE 8 CHECKS PASSED");}}
